        publishId(created)
        safe {
            // Tətbiq bu arada arxa fona keçibsə AppOpen göndərilmir.
            if (foreground && callbacks?.left != true) created.onForeground(tracked = callbacks != null, at = at) else created.refreshConfig()
            publishId(created)
        }
        safe { schedule(exec, created) }
    }

    /** Gözləmə siyahısına əlavə edir. Yalnız `lock` altında çağırılır. */
    private fun addPending(entry: Pending) {
        if (entry.kind == KIND_CALL) {
            // Adi çağırışlar məhdud sayda saxlanır; atılanlar sayılır və başlanğıcda sazlama loquna yazılır.
            if (pendingCalls >= MAX_PENDING) {
                droppedCalls++
                return
            }
            pendingCalls++
            pending.add(entry)
            return
        }
        // Razılıq, reset və həyat dövrü çağırışları heç vaxt atılmır. Siyahı böyüməsin deyə ardıcıl gələn eyni növ
        // çağırışlardan yalnız sonuncusu qalır; razılığı (analitika və ya reklam) geri alan çağırış onu yenidən verən
        // çağırışla əvəz olunmur (aradakı silinmə itməsin).
        val last = pending.lastOrNull()
        val keepsWithdrawal = last != null && ((last.denies && !entry.denies) || (last.deniesAds && !entry.deniesAds))
        if (last != null && last.kind == entry.kind && entry.kind != KIND_RESTRICT && !keepsWithdrawal) {
            pending[pending.size - 1] = entry
            last.discard?.invoke()
            return
        }
        if (pending.size - pendingCalls >= MAX_PENDING && entry.kind != KIND_RESTRICT) {
            val index = pending.indexOfLast { it.kind == entry.kind }
            if (index >= 0) pending.removeAt(index).discard?.invoke()
        }
        pending.add(entry)
    }

    private fun post(
        kind: Int = KIND_CALL,
        denies: Boolean = false,
        deniesAds: Boolean = false,
        discard: (() -> Unit)? = null,
        droppable: Boolean = false,
        call: (Core) -> Unit,
    ) {
        try {
            val exec: ScheduledExecutorService?
            synchronized(lock) {
                if (disabled) {
                    discard?.invoke()
                    return
                }
                if (core == null) {
                    // init hələ bitməyib: çağırış yadda saxlanır.
                    addPending(Pending(kind, denies, deniesAds, call, discard))
                    return
                }
                exec = executor
            }
            if (exec == null) {
                discard?.invoke()
                return
            }
            // İşçi axın yavaş sorğuda ilişibsə onun növbəsi hədsiz böyüməməlidir: `track` / `screen` çağırışlarından ən
            // çoxu [MAX_PENDING] gözləyir və dolanda ən KÖHNƏSİ atılır (ən yeni vəziyyət qalır). `identify`, razılıq,
            // `reset`, `flush`, keçid və həyat dövrü çağırışları heç vaxt atılmır; sıra dəyişmir.
            var start = false
            synchronized(jobLock) {
                if (droppable) {
                    if (jobsDroppable >= MAX_PENDING) {
                        val iterator = jobs.iterator()
                        while (iterator.hasNext()) {
                            if (iterator.next().droppable) {
                                iterator.remove()
                                break
                            }
                        }
                        backlogDropped.incrementAndGet()
                    } else {
                        jobsDroppable++
                    }
                }
                jobs.addLast(Job(droppable, call, discard))
                if (!draining) {
                    draining = true
                    start = true
                }
            }
            if (start) {
                try {
                    exec.execute { drain() }
                } catch (t: Throwable) {
                    // İşçi axın bağlanıb: gözləyən çağırışlar icra olunmayacaq, qoyduqları qadağalar götürülür.
                    val lost = synchronized(jobLock) {
                        draining = false
                        jobsDroppable = 0
                        ArrayList(jobs).also { jobs.clear() }
                    }
                    for (job in lost) safe { job.discard?.invoke() }
                    Log.w(TAG, "call failed", t)
                }
            }
        } catch (t: Throwable) {
            Log.w(TAG, "call failed", t)
            safe { discard?.invoke() }
        }
    }

    /** İşçi axında: gözləyən çağırışları gəliş sırası ilə, növbə boşalana qədər icra edir. */
    private fun drain() {
        try {
            while (true) {
                val job = synchronized(jobLock) {
                    val next = jobs.pollFirst()
                    if (next == null) draining = false else if (next.droppable) jobsDroppable--
                    next
                } ?: return
                safe {
                    core?.let {
                        val dropped = backlogDropped.getAndSet(0)
                        if (dropped > 0) it.note("$dropped track / screen calls made while the SDK was busy were dropped, oldest first (limit $MAX_PENDING)")
                        job.call(it)
                        publishId(it)
                    }
                }
            }
        } catch (t: Throwable) {
            synchronized(jobLock) { draining = false }
            throw t
        }
    }

    private fun schedule(exec: ScheduledExecutorService, core: Core) {
        val interval = core.flushIntervalMs
        exec.schedule({
            if (inForeground) safe { core.flush() }
            // Konfiq dəyişə bilər, ona görə növbəti fasilə hər dəfə yenidən oxunur.
            safe { schedule(exec, core) }
        }, interval, TimeUnit.MILLISECONDS)
    }

    /** Proses hazırda ön plandadırsa true. */
    private fun isForeground(): Boolean = try {
        val info = ActivityManager.RunningAppProcessInfo()
        ActivityManager.getMyMemoryState(info)
        info.importance == ActivityManager.RunningAppProcessInfo.IMPORTANCE_FOREGROUND
    } catch (t: Throwable) {
        false
    }

    /** Yalnız testlər üçün (refleksiya ilə çağırılır): işçi axındakı bütün gözləyən işlər bitənə qədər gözləyir. */
    @Suppress("unused")
    private fun awaitIdle() {
        val exec = synchronized(lock) { executor } ?: return
        try {
            exec.submit {}.get(10, TimeUnit.SECONDS)
        } catch (t: Throwable) {
            // Başlanğıc alınmayıbsa axın artıq bağlanıb.
        }
    }

    /** Yalnız testlər üçün (refleksiya ilə çağırılır): SDK-nı başlamamış vəziyyətə qaytarır. */
    @Suppress("unused")
    private fun shutdown() {
        awaitIdle()
        synchronized(lock) {
            executor?.shutdownNow()
            executor = null
            core = null
            lifecycle?.detach()
            lifecycle = null
            pending.clear()
            pendingCalls = 0
            droppedCalls = 0
            disabled = false
        }
        gate.clear()
        tombstone.reset()
        synchronized(jobLock) {
            jobs.clear()
            jobsDroppable = 0
            draining = false
        }
        backlogDropped.set(0)
        synchronized(idLock) {
            idHolds = 0
            anonymousId = null
        }
        inForeground = true
        manualLink = null
        transportFactory = { HttpTransport(it) }
        adIdFactory = { PlayAdId(it) }
    }

    private class Lifecycle(
        private val application: Application,
        private var foreground: Boolean,
        private val wrapper: Boolean,
    ) : Application.ActivityLifecycleCallbacks {
        private val handler = Handler(Looper.getMainLooper())

        /**
         * Hazırda görünən (started) Activity-lər. SDK gec başladılıbsa əvvəldən görünən Activity ilk
         * `onResume` / `onPause` çağırışında buraya düşür, ona görə sayğac heç vaxt yanlış başlamır.
         */
        private val started: MutableSet<Activity> = Collections.newSetFromMap(WeakHashMap<Activity, Boolean>())

        /** Hər Activity-nin artıq nəzərə alınmış keçidi (yoxdursa boş mətn). */
        private val links = WeakHashMap<Activity, String>()

        /** Arxa fona keçid ən azı bir dəfə təsdiqlənibsə true. */
        @Volatile
        var left = false
            private set

        private val toBackground = Runnable {
            guard {
                if (started.isEmpty() && foreground) {
                    foreground = false
                    inForeground = false
                    left = true
                    post(KIND_LIFECYCLE) { it.onBackground() }
                }
            }
        }

        /** Həyat dövrü çağırışları tətbiqin əsas axınında gəlir: SDK-nın heç bir xətası oraya ötürülmür. */
        private inline fun guard(block: () -> Unit) {
            try {
                block()
            } catch (t: Throwable) {
                try {
                    Log.w(TAG, "lifecycle callback failed", t)
                } catch (ignored: Throwable) {
                    // Log da alınmırsa susulur.
                }
            }
        }

        fun attach() = application.registerActivityLifecycleCallbacks(this)

        fun detach() {
            application.unregisterActivityLifecycleCallbacks(this)
            handler.removeCallbacks(toBackground)
        }

        override fun onActivityCreated(activity: Activity, savedInstanceState: Bundle?) = guard {
            // Fırlanma və ya sistemin bərpası: intent köhnədir, keçid artıq sayılıb.
            if (savedInstanceState != null) baseline(activity)
        }

        override fun onActivityStarted(activity: Activity) = guard {
            handler.removeCallbacks(toBackground)
            started.add(activity)
            inForeground = true
            if (!foreground) {
                foreground = true
                val at = System.currentTimeMillis()
                post(KIND_LIFECYCLE) { it.onForeground(at = at) }
            }
            deepLink(activity)
        }

        override fun onActivityResumed(activity: Activity) = guard {
            started.add(activity)
            baseline(activity)
            if (!wrapper) {
                val name = activity.javaClass.simpleName
                val at = System.currentTimeMillis()
                post(droppable = true) { it.screen(name, null, Core.ORIGIN_AUTO, at) }
            }
        }

        override fun onActivityPaused(activity: Activity) = guard {
            started.add(activity)
            baseline(activity)
        }

        override fun onActivityStopped(activity: Activity) = guard {
            started.remove(activity)
            baseline(activity)
            // Fırlanmada Activity dərhal yenidən yaranır: bu, arxa fona keçid deyil.
            if (!activity.isChangingConfigurations && started.isEmpty()) {
                handler.removeCallbacks(toBackground)
                handler.postDelayed(toBackground, BACKGROUND_DELAY_MS)
            }
        }

        /**
         * Activity-nin intent-indəki keçid. «Son tətbiqlər» siyahısından açılan Activity köhnə intent-i yenidən alır
         * (`FLAG_ACTIVITY_LAUNCHED_FROM_HISTORY`): bu, yeni keçid deyil.
         */
        private fun link(activity: Activity): String = try {
            val intent = activity.intent
            if (intent == null || intent.action != Intent.ACTION_VIEW || intent.flags and Intent.FLAG_ACTIVITY_LAUNCHED_FROM_HISTORY != 0) {
                ""
            } else {
                intent.dataString.orEmpty()
            }
        } catch (t: Throwable) {
            ""
        }

        /** SDK-nın yaranmasını görmədiyi Activity-nin hazırkı intent-i yeni keçid sayılmır. */
        private fun baseline(activity: Activity) {
            if (wrapper || links.containsKey(activity)) return
            links[activity] = link(activity).take(Util.MAX_URL_LENGTH + 1)
        }

        /**
         * Keçid yalnız yeni yaranmış Activity-nin ilk `onStart`-ında və ya tətbiq `setIntent` ilə intent-i
         * dəyişəndən sonra sayılır. Örtüklərdə (React Native, Flutter) keçidi örtük özü ötürür.
         */
        private fun deepLink(activity: Activity) {
            if (wrapper) return
            // Həddən uzun ünvanın yalnız başlanğıcı (müqayisə üçün) saxlanır; özü heç bir emaldan keçmir.
            val url = link(activity).take(Util.MAX_URL_LENGTH + 1)
            val changed = links[activity] != url
            links[activity] = url
            if (!changed || url.isEmpty()) return
            if (url.length > Util.MAX_URL_LENGTH) {
                post { it.note("deep link is longer than ${Util.MAX_URL_LENGTH} characters, ignored") }
                return
            }
            if (url == manualLink && SystemClock.elapsedRealtime() - manualLinkAt < MANUAL_LINK_WINDOW_MS) {
                manualLink = null
                return
            }
            val at = System.currentTimeMillis()
            post { it.onDeepLink(url, auto = true, at = at) }
        }

        override fun onActivitySaveInstanceState(activity: Activity, outState: Bundle) {}
        override fun onActivityDestroyed(activity: Activity) {}
    }
}
